designs.api_spec:
paths:
  /items:
    post:
      responses:
        '201': { description: Created }
        '422': { description: Empty title }

paths:
  /items/{item_id}/complete:
    post:
      responses:
        '200': { description: Completed }
        '404': { description: Unknown item }

paths:
  /items/{item_id}:
    delete:
      responses:
        '200': { description: Deleted }
        '404': { description: Unknown item }
